// Package agentusageview is the `:agent-usage` screen: the Claude Code
// sessions found on this machine.
//
// It reads transcripts' working directory and date only, never their content
// (internal/agentusage owns that guarantee).
package agentusageview

import (
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// sessionRow is one table row. project is computed once, in Update, so a Cell
// never touches the file system or the environment.
type sessionRow struct {
	agentusage.Session
	project string // theme.FoldHome(Project), or "-" when unknown
}

// sessionListLoadedMsg carries one listing. gen drops an answer to a read that
// a newer one has superseded.
type sessionListLoadedMsg struct {
	gen     int
	root    string
	listing agentusage.Listing
	err     error
}

// Model is the agent usage view.
type Model struct {
	table   datatable.Model[sessionRow]
	spinner spinner.Model
	footer  sharedcomponents.FooterMessage

	// gen numbers the reads; only the answer to the latest one is kept.
	gen     int
	loading bool
	// loadErr says the most recent read failed. It is a state rather than a
	// timed message so the empty-listing sentence cannot take its place.
	loadErr bool
	// root is the projects directory the last successful read listed.
	root    string
	omitted int
}

// New builds the view with its first read pending.
func New(_ *config.Config) Model {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	return Model{
		loading: true,
		spinner: sp,
		table: datatable.New(datatable.Config[sessionRow]{
			Columns: sessionColumns(),
			// The listing arrives newest first, which is the order wanted.
			SortColumn: -1,
		}),
	}
}

// Init starts the first read and the spinner.
func (m Model) Init() tea.Cmd {
	return tea.Batch(listSessionsCmd(m.gen), m.spinner.Tick)
}
package agentusageview

import (
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
)

// listSessionsCmd resolves the projects root and lists it, all inside the Cmd:
// the model is not touched (Rule 110) and the answer carries gen back.
func listSessionsCmd(gen int) tea.Cmd {
	return func() tea.Msg {
		root, err := agentusage.ProjectsRoot()
		if err != nil {
			return sessionListLoadedMsg{gen: gen, err: err}
		}
		listing, err := agentusage.ListSessions(root)
		return sessionListLoadedMsg{gen: gen, root: root, listing: listing, err: err}
	}
}
package agentusageview

import (
	"log"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Update handles messages.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		// The full viewport width, borders included (Rule 116).
		m.table.Resize(msg.Width, max(msg.Height-1, 1))
		return m, nil
	case sessionListLoadedMsg:
		return m.handleListLoaded(msg)
	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)
	case tea.KeyMsg:
		return m.handleKey(msg)
	}
	m.footer.Handle(msg)
	return m, nil
}

// handleListLoaded takes a listing, or ignores one from a superseded read.
// A failed read keeps the rows already shown: they are dated, not wrong.
func (m Model) handleListLoaded(msg sessionListLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.gen != m.gen {
		return m, nil
	}
	m.loading = false
	if msg.err != nil {
		// The error can name a path; it is logged, never shown (Rule 128).
		log.Printf("ERROR [agentusageview] list sessions: %v", msg.err)
		m.loadErr = true
		return m, nil
	}
	m.loadErr = false
	m.root = msg.root
	m.omitted = msg.listing.Omitted
	m.table.SetItems(rowsOf(msg))
	return m, nil
}

// rowsOf folds each project once, so no Cell does it per frame.
func rowsOf(msg sessionListLoadedMsg) []sessionRow {
	rows := make([]sessionRow, len(msg.listing.Sessions))
	for i, s := range msg.listing.Sessions {
		project := noProject
		if s.Project != "" {
			project = theme.FoldHome(s.Project)
		}
		rows[i] = sessionRow{Session: s, project: project}
	}
	return rows
}

// handleSpinnerTick advances the spinner only while a read is in flight, so the
// chain ends with the load.
func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
	if !m.loading {
		return m, nil
	}
	var cmd tea.Cmd
	m.spinner, cmd = m.spinner.Update(msg)
	m.footer.SetSpinnerFrame(m.spinner.View())
	return m, cmd
}

// handleKey gives the filter the keyboard first; ctrl+r refreshes.
func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if !m.InEditMode() && msg.String() == "ctrl+r" {
		return m.refresh()
	}
	return m, m.table.Update(msg)
}

// refresh starts a new read under a new generation. The rows stay on screen.
func (m Model) refresh() (tea.Model, tea.Cmd) {
	m.gen++
	m.loading = true
	m.loadErr = false
	return m, tea.Batch(listSessionsCmd(m.gen), m.spinner.Tick)
}

// InEditMode tells the router the filter has the keyboard.
func (m Model) InEditMode() bool { return m.table.FilterBar().InEditMode() }

// FilterBarVisible closes the viewport rectangle around the bar.
func (m Model) FilterBarVisible() bool { return m.table.FilterBar().IsVisible() }
package agentusageview

import (
	"strconv"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// baseFooterHeight is the blank line and the message line (Rule 124).
const baseFooterHeight = 2

// View is the table, whatever it holds (Rule 139).
func (m Model) View() string { return m.table.View() }

// GetTitle names the view.
func (m Model) GetTitle() string { return theme.IconAgentUsage + " Agent usage" }

// GetIcon returns nothing: the title carries the icon.
func (m Model) GetIcon() string { return "" }

// GetHeaderInfo counts the sessions on screen, and the ones not listed when
// there are some.
func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
	info := []shortcut.HeaderInfo{
		{Key: "Sessions", Value: strconv.Itoa(len(m.table.Visible())), Style: theme.HeaderValueStyle},
	}
	if m.omitted > 0 {
		info = append(info, shortcut.HeaderInfo{Key: "Skipped", Value: strconv.Itoa(m.omitted), Style: theme.HeaderValueStyle})
	}
	return info
}

// GetShortcuts returns the same keys in every state, none greyed: each one
// always acts here (Rule 130).
func (m Model) GetShortcuts() shortcut.Shortcuts {
	return shortcut.Shortcuts{
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "/", Description: "Filter"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight budgets the footer (Rules 124, 136).
func (m Model) GetFooterHeight() int {
	return baseFooterHeight + m.table.FilterBar().ExtraHeight()
}

// RenderFooter renders the filter bar when visible, a blank line, and the
// message line.
func (m Model) RenderFooter(width int) string {
	line := theme.EmptyLineBg(width) + "\n" + m.footer.View(width, m.status())
	if bar := m.table.FilterBar(); bar.IsVisible() {
		return bar.View() + "\n" + line
	}
	return line
}

// status is derived on every frame, with no timer (Rule 128).
//
// The empty sentence needs the listing to be empty in total, not after the
// filter: a filter with no match is not a machine with no sessions.
func (m Model) status() sharedcomponents.Status {
	switch {
	case m.loadErr:
		return sharedcomponents.Status{
			Text:  "Failed to list Claude Code sessions — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.loading:
		return sharedcomponents.Status{Text: "Reading Claude Code sessions...", Spinner: true}
	case len(m.table.Items()) == 0:
		return sharedcomponents.Status{Text: "No Claude Code sessions found in " + theme.FoldHome(m.root)}
	}
	return sharedcomponents.Status{}
}
package agentusageview

import (
	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	// noProject stands for a session whose transcript named no working directory.
	noProject = "-"
	// lastActiveLayout is the local date and time of the Last active column.
	lastActiveLayout = "2006-01-02 15:04"
	// sessionIDPrefix is how much of the ID the Session column shows.
	sessionIDPrefix = 8
)

// sessionColumns describes the sessions table.
//
// Project is the full path, home folded, cut from the left when it does not fit
// so the leaf — the part that names the project — stays visible. Session is the
// first thing to go on a narrow terminal.
func sessionColumns() []datatable.Column[sessionRow] {
	return []datatable.Column[sessionRow]{
		{
			Title: "Project", Sizing: datatable.SizingContent,
			MinWidth: 20, Flex: 3, TruncateHead: true,
			Cell:   projectCell,
			Style:  projectStyle,
			Search: func(r sessionRow) string { return r.project },
			Less:   func(a, b sessionRow) bool { return a.project < b.project },
		},
		{
			Title: "Last active", Sizing: datatable.SizingFixed, MinWidth: len(lastActiveLayout),
			Cell: func(r sessionRow) string { return r.ModTime.Local().Format(lastActiveLayout) },
			Less: func(a, b sessionRow) bool { return a.ModTime.Before(b.ModTime) },
		},
		{
			Title: "Session", Sizing: datatable.SizingFixed, Optional: true, MinWidth: sessionIDPrefix,
			Cell: sessionIDCell,
			// The full ID is searched even though only its start is shown.
			Search: func(r sessionRow) string { return r.ID },
		},
	}
}

func projectCell(r sessionRow) string {
	if r.project == "" {
		return noProject
	}
	return r.project
}

// projectStyle dims the placeholder (Rule 122).
func projectStyle(r sessionRow) lipgloss.Style {
	if r.project == noProject {
		return theme.DimStyle
	}
	return lipgloss.NewStyle()
}

// sessionIDCell is the start of the ID; an ID shorter than that shows whole.
func sessionIDCell(r sessionRow) string {
	id := []rune(r.ID)
	return string(id[:min(sessionIDPrefix, len(id))])
}
