// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
// its branch.
func roleCell(r agentRow) string {
	if r.Main {
		return orchestratorLabel
	}
	typ := r.Type
	if typ == "" {
		typ = unknownType
	}
	if r.last {
		return lastStem + typ
	}
	return stem + typ
}

// modelsCell lists the models the agent used.
func modelsCell(r agentRow) string {
	if len(r.Models) == 0 {
		return noModel
	}
	return strings.Join(r.Models, ", ")
}

// outCell is the output count. A sub-agent still being written is a floor and
// says so; the orchestrator never does, its transcript is the one being read.
func outCell(r agentRow) string {
	out := formatTokens(r.Tokens.Output)
	if !r.Main && r.PartialOutput() {
		return partialMark + out
	}
	return out
}

// formatTokens renders a count compactly, floored to one decimal: 1099 is
// "1.0k", never "1.1k". From 100k up the decimal is dropped.
func formatTokens(n int64) string {
	units := []struct {
		size   int64
		suffix string
	}{
		{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
	}
	for _, u := range units {
		if n < u.size {
			continue
		}
		tenths := n / (u.size / 10) // divide first: n*10 would overflow
		if u.suffix == "k" && tenths >= 1000 {
			return fmt.Sprintf("%dk", tenths/10)
		}
		return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
	}
	return fmt.Sprintf("%d", n)
}

// Update handles the keys every table shares: navigation, `/` for the search,
// `.` for the sort, and whatever the filter bar takes while it is focused.
// Anything else is left alone, so the view keeps its own actions.
func (m *Model[T]) Update(msg tea.Msg) tea.Cmd {
	if m.bar.InEditMode() {
		var cmd tea.Cmd
		m.bar, cmd = m.bar.Update(msg)
		m.rebuild()
		// A search that keeps only short values has to give the room back, or
		// the filter buys nothing visually. It is a user action on a settled
		// population, which is exactly a measurement moment.
		m.Remeasure()
		return cmd
	}

	key, ok := msg.(tea.KeyMsg)
	if !ok {
		return nil
	}
	switch key.String() {
	case "/":
		// A table with nothing to search does not claim the key: activating a
		// search that can only ever match nothing would empty the list, and the
		// bar the user needs to see why is not in that view's footer.
		if !m.Searchable() {
			return nil
		}
		return m.bar.ActivateSearch()
	case ".":
		m.CycleSort()
	// No bare letter is navigation (§3.26). The vim aliases h/j/k/l/g/G are
	// gone application-wide: home/end already covered g/G, and keeping j/k
	// alone would leave the one exception that makes the rule unverifiable.
	// The letters now belong to the action vocabulary — internal/ui/keymap.
	case "up":
		m.table.MoveUp(1)
		m.afterCursorMove()
	case "down":
		m.table.MoveDown(1)
		m.afterCursorMove()
	case "pgup":
		m.table.MoveUp(m.table.Height())
		m.afterCursorMove()
	case "pgdown":
		m.table.MoveDown(m.table.Height())
		m.afterCursorMove()
	case "home":
		m.table.GotoTop()
		m.afterCursorMove()
	case "end":
		m.table.GotoBottom()
		m.afterCursorMove()
	}
	return nil
}

